function notify(text){const n=$('#notice');n.innerHTML=`<span class="toasticon">✿</span>${text}`;n.classList.add('on');clearTimeout(notify.t);notify.t=setTimeout(()=>n.classList.remove('on'),2600)}
function updateHUD(){ $('#money').textContent=state.money;$('#bagCount').textContent=Object.values(state.inventory).reduce((a,b)=>a+b,0);$('#clock').textContent=`${Math.floor(timeOfDay)%12||12}:${String(Math.floor(timeOfDay%1*60/10)*10).padStart(2,'0')} ${timeOfDay>=12?'PM':'AM'}`;$('#weather').textContent=weather;$('#weatherIcon').textContent=state.rain?'🌧️':'☀️';$('#location').textContent=currentMode==='home'?'HOME · KITCHEN':currentMode==='garden'?'HOME · BACK GARDEN':'VILLAGE · LITTLE MARKET';$('#objectiveTitle').textContent=state.coffee?'A lovely little ritual':'A slow morning';$('#objectiveText').textContent=state.coffee?'Your day is yours to shape.':`Make a cup of something lovely · ${state.money} coins in your purse.`;}
function addItem(n,q=1){state.inventory[n]=(state.inventory[n]||0)+q;if(state.inventory[n]<=0)delete state.inventory[n];save()}
function has(n,q=1){return (state.inventory[n]||0)>=q}
function consume(n,q=1){if(!has(n,q))return false;addItem(n,-q);return true}
function openPanel(eyebrow,title,body,wide=false){$('#panel').classList.toggle('wide',wide);$('#panel').innerHTML=`<div class="panelhead"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2></div><button class="close" aria-label="Close">×</button></div>${body}`;$('#panelWrap').classList.add('open');$('#panel .close').onclick=closePanel;}
function closePanel(){ $('#panelWrap').classList.remove('open');}
function btn(label,fn,primary=false){const b=document.createElement('button');b.className='softbtn'+(primary?' primary':'');b.textContent=label;b.onclick=fn;return b}
function panelAction(label,fn,primary=false){const row=$('#panel .action-row')||(()=>{const d=document.createElement('div');d.className='action-row';$('#panel').appendChild(d);return d})();row.appendChild(btn(label,fn,primary));}
function showInventory(){const items=Object.entries(state.inventory);openPanel('YOUR SATCHEL','Little things you carry',items.length?`<p>Everything you’ve gathered along the way.</p><div class="inventory-list">${items.map(([n,q])=>`<span class="invitem">${itemIcon(n)} ${n} <b>×${q}</b></span>`).join('')}</div>`:'<div class="inventory-empty">Your satchel is light as a feather. Visit the market for supplies.</div>');}
function itemIcon(n){return ({'Coffee beans':'☕','Milk':'🥛','Cat food':'🐟','Tomato seeds':'🍅','Carrot seeds':'🥕','Basil seeds':'🌿','Fresh bread':'🍞','Watering can':'🚿','Latte':'☕','Cappuccino':'☕','Cortado':'☕','Americano':'☕','Mocha':'🍫','Affogato':'🍨','Tomato tart':'🥧','Garden bouquet':'💐','Jam scone':'🥐'})[n]||'✿'}
$('#bagBtn').onclick=showInventory;

let groundBeans=false, shotReady=false, tvScreen=null, filmCanvas=null, filmCtx=null, filmTexture=null, activeFilm='';
function coffeeMenu(){let body='<p>Your little coffee corner is ready. Take your time; it’s all about the ritual.</p><div class="action-row"></div><div class="cards">'+[['☕ Grind beans','Takes a small handful of good beans.'],['✧ Pull espresso','A rich little shot, just right.'],['♨ Steam milk','For something soft and silky.']].map(([a,b])=>`<div class="card"><div class="cardtext"><strong>${a}</strong><small>${b}</small></div></div>`).join('')+'</div>';openPanel('KITCHEN · COFFEE CORNER','A proper little coffee',body);panelAction(groundBeans?'✓ Beans ground':'1 · Grind beans',()=>{if(!has('Coffee beans'))return notify('A little trip to the market for beans first.');consume('Coffee beans');groundBeans=true;notify('The kitchen fills with that lovely roasted smell.');coffeeMenu()},true);panelAction(shotReady?'✓ Espresso pulled':'2 · Pull a shot',()=>{if(!groundBeans)return notify('Grind some beans first.');groundBeans=false;shotReady=true;notify('A tiny, perfect espresso shot.');coffeeMenu()});panelAction('3 · Steam milk',()=>{if(!has('Milk'))return notify('You’re all out of milk. The market has some.');notify('Milk steamed to a soft little cloud.');coffeeMenu()});panelAction('Choose a drink ↓',()=>$('#recipes').scrollIntoView({behavior:'smooth'}));
 const d=document.createElement('div');d.id='recipes';d.innerHTML='<p style="margin-bottom:5px"><b>Make something lovely</b> <span style="color:#78866c">· first pull a shot</span></p><div class="cards">'+['Latte','Cortado','Cappuccino','Americano','Mocha','Affogato'].map(n=>`<div class="card"><div class="cardtext"><strong>${itemIcon(n)} ${n}</strong><small>${recipeDesc(n)}</small></div><button class="buy" data-drink="${n}">Make</button></div>`).join('')+'</div>';$('#panel').appendChild(d);d.querySelectorAll('[data-drink]').forEach(b=>b.onclick=()=>makeDrink(b.dataset.drink));}
function recipeDesc(n){return ({Latte:'Espresso + steamed milk',Cortado:'A little coffee, equal milk',Cappuccino:'Espresso + velvety foam',Americano:'Espresso softened with water',Mocha:'Coffee with a little chocolate',Affogato:'A scoop of ice cream + espresso'})[n]}
function makeDrink(n){if(!shotReady)return notify('Pull a fresh espresso shot first.');if(['Latte','Cortado','Cappuccino','Mocha'].includes(n)&&!has('Milk'))return notify('You’ll need some milk from the market.');if(n==='Mocha'&&!has('Chocolate syrup'))return notify('Mocha needs chocolate syrup from the market.');if(n==='Affogato'&&!has('Vanilla ice cream'))return notify('An affogato needs vanilla ice cream.');shotReady=false;if(['Latte','Cortado','Cappuccino','Mocha'].includes(n))consume('Milk');if(n==='Mocha')consume('Chocolate syrup');if(n==='Affogato')consume('Vanilla ice cream');addItem(n);state.coffee++;state.money+=2;state.recipes=[...new Set([...state.recipes,n])];save();notify(`A ${n.toLowerCase()} made with love. +2 coins`);coffeeMenu()}
function tvMenu(){openPanel('KITCHEN · MAGNAVOX 1958','A little movie night','<p>A tiny woodgrain television, warm as toast. The DVD player is ready for one of your very favorite stories.</p><div class="cards" id="dvdcards"></div><div class="action-row"></div>');const root=$('#dvdcards');state.dvd.forEach((name,i)=>{const div=document.createElement('div');div.className='card';div.innerHTML=`<div class="cardtext"><strong>📼 ${name}</strong><small>Original little fantasy · ${i===0?'The woods remember':'A quiet ocean tale'}</small></div><button class="buy">${activeFilm===name?'Playing':'Play'}</button>`;div.querySelector('button').onclick=()=>playFilm(name);root.appendChild(div)});panelAction('Turn the TV off',()=>{activeFilm='';if(tvScreen){tvScreen.material=mat('#313b37',.25);tvScreen.material.emissive=new THREE.Color('#000000')}closePanel();notify('The little screen fades to dark.')} );panelAction('Collect DVDs',()=>dvdMenu())}
function dvdMenu(){openPanel('THE DVD SHELF','Stories for a rainy afternoon','<p>Two original little films, made just for this cottage. Pick up a case, read its cover, and keep it for movie night.</p><div class="cards">'+state.dvd.map((n,i)=>`<div class="card"><div class="cardtext"><strong>🎞 ${n}</strong><small>${i?'A shy sea spirit befriends a lighthouse keeper.':'A forest lantern guides a lost postman home.'}</small></div><button class="buy" data-dvd="${n}">${state.collected.includes(n)?'Inspect':'Pick up'}</button></div>`).join('')+'</div>');$('#panel').querySelectorAll('[data-dvd]').forEach(b=>b.onclick=()=>{const n=b.dataset.dvd;if(!state.collected.includes(n)){state.collected.push(n);save();notify(`You picked up “${n}”. The cover is lovely.`);dvdMenu()}else openPanel('A FILM CASE',n,`<p>${n==='The Lantern in the Pines'?'A forest lantern guides a lost postman home, one quiet evening at a time.':'A shy sea spirit befriends a lighthouse keeper and learns the names of the stars.'}</p>`)});panelAction('Take a seat & watch',()=>{closePanel();tvMenu()})}
function playFilm(name){activeFilm=name;closePanel();timeOfDay+=1;state.movie=true;save();if(tvScreen){tvScreen.material=filmTexture?new THREE.MeshBasicMaterial({map:filmTexture}):mat('#77916c');}notify(`Now showing: ${name} · get comfy.`);$('#objectiveTitle').textContent='A little movie night';$('#objectiveText').textContent='A warm screen, a good cup, and nowhere to be.'}
function chore(which){if(which==='dishes'){state.dishes=0;state.money+=1;notify('The dishes sparkle in the morning light. +1 coin');}
 if(which==='wash'){if(state.dishes>=3){state.dishes=0;notify('The sink is already beautifully clear.')}else{state.dishes+=1;notify('A little warm water and a clean sink.')} }
 if(which==='laundry'){if(!has('Laundry detergent'))return notify('You’ll need detergent from the village market.');if(state.laundry===0){consume('Laundry detergent');state.laundry=1;notify('A gentle wash is tumbling away. Come back after a little while.')}else notify('The washing machine is already humming softly.')}
 if(which==='fold'){if(!state.laundry)return notify('No clean washing yet. Start a load in the laundry corner.');state.laundry=0;state.money+=2;notify('Fresh, warm laundry folded into a neat little stack. +2 coins')}
 if(which==='clean'){state.clean=1;state.money+=1;notify('A little tidy makes the room feel new. +1 coin')}
 save();}
function openCabinet(){openPanel('KITCHEN · LITTLE CUPBOARD','Everything in its place','<p>Take a peek in the cupboard. A few cozy basics are always here.</p><div class="cards"><div class="card"><div class="cardtext"><strong>Fresh bread</strong><small>Warm, crusty, just right for breakfast.</small></div><button class="buy" id="bread">Take one · 2</button></div><div class="card"><div class="cardtext"><strong>Breakfast toast</strong><small>Something simple and lovely.</small></div><button class="buy" id="toast">Make toast</button></div></div>');$('#bread').onclick=()=>{if(state.money<2)return notify('A couple of coins short. Sell something at the village stall.');state.money-=2;addItem('Fresh bread');notify('A little loaf for the morning.');openCabinet()};$('#toast').onclick=()=>{if(!has('Fresh bread'))return notify('Pick up a loaf first.');consume('Fresh bread');state.money++;notify('Toasty breakfast, and a coin for your troubles.');save();openCabinet()}}
function sleep(){timeOfDay=7.6;state.day++;season=['Spring','Summer','Autumn','Winter'][(Math.floor((state.day-1)/7))%4];weather=Math.random()<.25?'Rainy morning':'Soft sunshine';state.rain=weather.includes('Rain');for(let i=0;i<state.garden.length;i++){const p=state.garden[i];if(p){p.days++;if(p.watered){p.grow=(p.grow||0)+1;p.watered=false}}}save();notify(`A fresh ${season.toLowerCase()} morning. Day ${state.day} begins.`)}
function journal(){openPanel('YOUR LITTLE JOURNAL',`Day ${state.day} · ${season}`,`<p>${state.recipes.length?`You've learned ${state.recipes.join(', ')}. `:'A good day begins with a little curiosity. '}${state.cats.length?`At home with ${state.cats.map(c=>c.name).join(' and ')}. `:'A little visitor may come by the garden.'}</p><p><b>Today’s weather:</b> ${weather}<br><b>Garden:</b> ${state.garden.filter(Boolean).length} little beds growing<br><b>Neighbors helped:</b> ${Math.floor(state.money/5)} times (more or less!)</p><p>Try planting a few seeds, making a new drink, or simply sitting down for a film.</p>`);panelAction('Sleep until morning',()=>{sleep();closePanel()})}

function gardenMenu(i){const p=state.garden[i];openPanel('BACK GARDEN',`Bed ${i+1} · ${season.toLowerCase()} soil`,p?`<p>${p.name} is ${p.grow>=2?'ready to harvest':p.watered?'enjoying a good drink':`growing quietly · ${Math.min(2,p.grow||0)}/2 sunny days`}.</p><div class="action-row"></div>`:'<p>A little patch of dark, soft soil. Plant something you love.</p><div class="action-row"></div>');
 if(!p){for(const [seed,produce] of [['Tomato seeds','Tomatoes'],['Carrot seeds','Carrots'],['Basil seeds','Fresh basil'],['Flower seeds','Garden bouquet']])panelAction(`Plant ${seed.replace(' seeds','').toLowerCase()}`,()=>{if(!has(seed))return notify(`Pick up ${seed.toLowerCase()} at the market first.`);consume(seed);state.garden[i]={name:produce,grow:0,watered:false,days:0};state.planted++;save();notify(`${produce} tucked into the earth. Give it a drink!`);gardenMenu(i)},true)}
 else {panelAction(p.watered?'✓ Watered for today':'Water the little plant',()=>{if(p.watered)return notify('That little plant has had a drink today.');p.watered=true;state.watered++;save();notify(`A good drink for the ${p.name.toLowerCase()}.`);gardenMenu(i)},true);if((p.grow||0)>=2)panelAction(`Harvest ${p.name}`,()=>{addItem(p.name);state.garden[i]=null;state.money+=2;save();notify(`${p.name} picked fresh! +2 coins`);gardenMenu(i)});panelAction('Leave this patch to rest',()=>{state.garden[i]=null;save();gardenMenu(i)})}}
function feedStray(){if(!has('Cat food'))return notify('A little cat food would make a lovely offering. The market has some.');consume('Cat food');state.trust++;save();notify('You set down a little bowl, then give your visitor some space. Trust is growing.');if(state.trust>=2&&!state.cats.length){setTimeout(()=>{if(!state.cats.length)adoptPrompt()},700)}}
function catInteraction(){if(state.cats.length){const c=state.cats[state.cats.length-1];openPanel('A GARDEN VISITOR',`${c.name} says hello`,`<p>${c.personality} Their tail gives a gentle little swish as they watch you.</p><div class="action-row"></div>`);panelAction('Give a gentle pet',()=>{notify(`${c.name} leans into your hand. A tiny purr!`);closePanel()});panelAction('Offer cat food',()=>{if(!has('Cat food'))return notify('The market has tasty little meals.');consume('Cat food');notify(`${c.name} munches happily.`);save();closePanel()});panelAction('Invite inside',()=>{travel('home');notify(`${c.name} pads after you, curious about the house.`);closePanel()});return}
 openPanel('A GARDEN VISITOR','A little friend is near',`<p>A shy ${['ginger','soft gray','patchy calico'][state.trust%3]} cat is peeking from the garden. ${state.trust?'They seem to remember your kindness.':'A bowl of food might help them feel safe.'}</p>`);panelAction('Leave a little food',()=>{closePanel();feedStray()},true);panelAction('Speak softly',()=>{state.trust++;save();notify('A quiet hello. Your visitor seems a little less shy.');if(state.trust>=2)adoptPrompt()})}
function adoptPrompt(){if(state.cats.length>=3)return notify('Your cottage is already full of happy little whiskers.');const name=prompt('Your garden friend trusts you now. What shall you call them?','Mochi');if(!name)return;const personality=['an affectionate lap cat who loves a slow morning','a curious explorer who investigates every cupboard','a gentle daydreamer who naps in sunny patches'][state.cats.length%3];state.cats.push({name,personality});save();notify(`${name} is home! A new friend, with a ${personality.split(' who ')[0]}.`);const cat=buildCat(indoor,-1,.15,1.8,name);cat.scale.setScalar(.7);}
function shopItem(name){const prices={'Coffee beans':5,'Milk':3,'Chocolate syrup':4,'Vanilla ice cream':4,'Cat food':4,'Cat treats':3,'Toy mouse':5,'Laundry detergent':4,'Tomato seeds':2,'Carrot seeds':2,'Basil seeds':2,'Flower seeds':3,'Fresh bread':3,'Flour':3,'Furniture catalogue':8,'Watering can':6};const price=prices[name]||4;if(state.money<price)return notify(`You need ${price} coins for ${name}. Sell a few lovely things first.`);state.money-=price;addItem(name);notify(`${name} tucked into your satchel. −${price} coins.`);save()}
function sellInventory(){const sellables=['Latte','Cortado','Cappuccino','Americano','Mocha','Affogato','Tomatoes','Carrots','Fresh basil','Garden bouquet','Tomato tart','Jam scone'];let total=0,lines=[];for(const n of sellables)if(has(n)){let q=state.inventory[n];let price=['Latte','Cortado','Cappuccino','Americano','Mocha','Affogato'].includes(n)?6:['Garden bouquet'].includes(n)?8:4;consume(n,q);total+=q*price;lines.push(`${q} ${n}`)}if(total){state.money+=total;save();notify(`A neighbor loved your ${lines.join(', ')}! +${total} coins`)}else notify('Nothing to sell just yet. Your neighbors love coffee, treats, and fresh garden things.');openPanel('THE VILLAGE STALL','A little trade, a lot of heart',`<p>Your neighbors picked up ${total?`your lovely ${lines.join(' and ')}. Everyone's happy.`:'nothing today.'} Homemade things are always better.</p><p><b>Purse:</b> ${state.money} coins</p>`);panelAction('Back to the market',()=>closePanel())}
function travel(where){closePanel();if(where==='village'){currentMode='shop';indoor.visible=false;garden.visible=false;shop.visible=true;camera.position.set(0,1.65,7.5);camera.rotation.set(0,Math.PI,0);$('#hint').textContent='';}
