function makeDrink(n){if(!shot)return notify('Pull a fresh espresso shot first.');if(['Latte','Cortado','Cappuccino','Mocha'].includes(n)&&!has('Milk'))return notify('You’ll need milk from the market.');if(n==='Mocha'&&!has('Chocolate syrup'))return notify('Mocha needs chocolate syrup from the market.');if(n==='Affogato'&&!has('Vanilla ice cream'))return notify('An affogato needs vanilla ice cream.');shot=false;if(['Latte','Cortado','Cappuccino','Mocha'].includes(n))take('Milk');if(n==='Mocha')take('Chocolate syrup');if(n==='Affogato')take('Vanilla ice cream');add(n);S.money+=2;drinkMade=true;S.recipes=[...new Set([...S.recipes,n])];save();notify(`${n} made with love. +2 coins`);coffeeMenu()}

function pantryMenu(){panel('COTTAGE · CUPBOARD','A little something to eat','<p>Make a simple meal from whatever you brought home.</p><div class="action-row"></div>');action(has('Fresh bread')?'Toast the fresh bread':'Buy bread at the market',()=>{if(!take('Fresh bread'))return notify('The baker at the market has lovely loaves.');add('Toast');S.money+=1;notify('Warm toast, and a coin for your little café fund.');pantryMenu()},true);action('Make garden salad',()=>{let produce=['Tomatoes','Carrots','Fresh basil'].filter(has);if(!produce.length)return notify('Grow something in the garden first.');take(produce[0]);add('Garden salad');S.money+=2;notify('A bright garden salad, made from your own harvest. +2 coins');pantryMenu()})}
function chore(which){if(which==='dishes'){if(!S.dirty)return notify('The sink is already sparkling.');S.dirty=0;notify('A few minutes at the sink, and everything gleams again.')}if(which==='wash'){S.clean=true;notify('A refreshing wash, and you feel a little brighter.')}if(which==='laundry'){if(S.laundry)return notify('The laundry is already waiting to be folded.');if(!has('Laundry detergent'))return notify('Pick up detergent at the village market first.');take('Laundry detergent');S.laundry=true;notify('The washer hums softly in the corner.')}if(which==='fold'){if(!S.laundry)return notify('There is no laundry to fold just now.');S.laundry=false;notify('Fresh, warm laundry folded into a neat little stack.')}if(which==='clean'){if(!S.dirty)return notify('The living room is already lovely and tidy.');S.dirty=0;notify('A quick tidy makes the whole cottage feel peaceful.')}S.chores=(S.chores||0)+1;save()}
function sleep(){panel('BEDROOM · REST','A new day, at your own pace','<p>Close your eyes, listen to the rain on the roof, and wake whenever you like.</p><div class="action-row"></div>');action('Sleep until morning',()=>{closePanel();S.day++;hour=7.5;grounded=false;shot=false;S.garden.forEach(p=>{if(p){p.days=(p.days||0)+1;if(p.watered)p.grow=Math.min(2,(p.grow||0)+1);p.watered=false}});weather=Math.random()<.25?'A gentle rain':'Soft sunshine';if(S.day%8===0)S.season=['Spring','Summer','Autumn','Winter'][(Math.floor((S.day-1)/8)+1)%4];S.money+=4;save();notify(`Day ${S.day} · ${weather.toLowerCase()} · a little neighborly thank-you of 4 coins.`)},true)}
function journal(){let grown=S.garden.filter(Boolean).length;panel('YOUR LITTLE JOURNAL',`Day ${S.day} · ${S.season}`,`<p>${weather}. The clock moves gently; nothing here needs to be hurried.</p><div class="cards"><div class="card"><div class="cardtext"><strong>🌱 Garden</strong><small>${grown} planted · ${S.planted||0} total plantings · ${S.garden.filter(p=>p&&(p.grow||0)>=2).length} ready to pick</small></div></div><div class="card"><div class="cardtext"><strong>☕ Little café</strong><small>${S.recipes.length?S.recipes.join(', '):'No recipes made yet'}</small></div></div><div class="card"><div class="cardtext"><strong>🐈 Neighborhood cats</strong><small>${S.cats.length?S.cats.join(', '):'A friendly face may visit the garden'}</small></div></div><div class="card"><div class="cardtext"><strong>🧺 Chores</strong><small>${S.chores||0} little acts of care · ${S.laundry?'Laundry to fold':'All caught up'}</small></div></div></div><p>Coins: ${S.money} · DVDs: ${S.dvds.join(' and ')} · ${S.collected.length} films enjoyed.</p><div class="action-row"></div>`);action('Close journal',closePanel)}
function bagMenu(){let items=Object.entries(S.bag).filter(([,n])=>n>0);panel('YOUR SATCHEL',`${items.reduce((a,[,n])=>a+n,0)} little things`,`<p>${items.length?items.map(([n,q])=>`<div class="card"><div class="cardtext"><strong>${n}</strong><small>In your satchel</small></div><b>× ${q}</b></div>`).join(''):'Just a little room for something lovely.'}</p><div class="action-row"></div>`);action('Close satchel',closePanel)}
